var soc = parseFloat(msg.payload.value);
var threshold = 20;

if (isNaN(soc)) return null;

// Only alert once per low event
var wasLow = flow.get('batteryWasLow') || false;

if (soc <= threshold && !wasLow) {
    flow.set('batteryWasLow', true);
    msg.payload = '⚠️ Battery LOW: ' + Math.round(soc) + '% - Connect to shore power!';
    msg.topic = 'Battery Alert';
    return [msg, null];
} else if (soc > threshold + 5) {
    flow.set('batteryWasLow', false);
}

// Pass SOC value for dashboard
var socMsg = {payload: soc};
return [null, socMsg];

var price = parseFloat(msg.payload.value);
if (isNaN(price)) return null;

var cheapThreshold = 5; // 5p/kWh
var wasNotified = flow.get('priceNotified_' + Math.floor(Date.now()/1800000)) || false;

if (price <= 0 && !wasNotified) {
    flow.set('priceNotified_' + Math.floor(Date.now()/1800000), true);
    msg.payload = '🟢 FREE ELECTRICITY! Price: ' + price + 'p/kWh - Charge everything now!';
    return msg;
} else if (price <= cheapThreshold && !wasNotified) {
    flow.set('priceNotified_' + Math.floor(Date.now()/1800000), true);
    msg.payload = '💰 Cheap electricity: ' + price + 'p/kWh - Good time to charge!';
    return msg;
}
return null;
